package com.ecommerce.product; import com.ecommerce.seller.SellerProfile; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="products") public class Product { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="seller_id",nullable=false) SellerProfile seller; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="category_id",nullable=false) Category category; @Column(nullable=false) String name; @Column(columnDefinition="TEXT") String description; @Column(nullable=false,precision=12,scale=2) BigDecimal price; @Enumerated(EnumType.STRING) @Column(nullable=false) Status status=Status.DRAFT; @Column(name="created_at",nullable=false,updatable=false) Instant createdAt; @Column(name="updated_at",nullable=false) Instant updatedAt; @PrePersist void c(){createdAt=Instant.now();updatedAt=createdAt;} @PreUpdate void u(){updatedAt=Instant.now();} public UUID getId(){return id;} public SellerProfile getSeller(){return seller;} public Category getCategory(){return category;} public String getName(){return name;} public String getDescription(){return description;} public BigDecimal getPrice(){return price;} public Status getStatus(){return status;} public void setSeller(SellerProfile v){seller=v;} public void setCategory(Category v){category=v;} public void setName(String v){name=v;} public void setDescription(String v){description=v;} public void setPrice(BigDecimal v){price=v;} public void setStatus(Status v){status=v;} public enum Status{DRAFT,ACTIVE,INACTIVE,ARCHIVED} }
